/* Добор живых схем. Сперва виртуальные потоки и dirty checking: в Concurrency все схемы
   были доломовские, в Spring не было ничего про persistence context.
   Дальше — закрытие самых пустых кластеров: на 100 карточек Java приходилось 5 схем,
   на 34 карточки DevOps — две. */
window.PRINCIPLES=(window.PRINCIPLES||[]).concat([
 {
  "id": "pr-vthreads",
  "t": "Concurrency",
  "title": "Виртуальные потоки",
  "what": "Виртуальный поток монтируется на несущий, а на блокирующем вызове снимается с него и уезжает в кучу — несущий тут же берёт следующий. Пока кадр нативный, снять нельзя: несущий закреплён.",
  "html": "<div style=\"position:relative;min-height:320px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good);white-space:nowrap\">10 000 виртуальных</span><div class=\"fp-row\" style=\"align-items:center;gap:8px;flex-wrap:wrap;justify-content:center;max-width:560px\"><span class=\"fp-token pr-bob\" style=\"padding:3px 8px;font-size:10px;color:var(--good);border-color:var(--good);animation-delay:0.00s\">VT</span><span class=\"fp-token pr-bob\" style=\"padding:3px 8px;font-size:10px;color:var(--good);border-color:var(--good);animation-delay:0.13s\">VT</span><span class=\"fp-token pr-bob\" style=\"padding:3px 8px;font-size:10px;color:var(--good);border-color:var(--good);animation-delay:0.26s\">VT</span><span class=\"fp-token pr-bob\" style=\"padding:3px 8px;font-size:10px;color:var(--good);border-color:var(--good);animation-delay:0.39s\">VT</span><span class=\"fp-token pr-bob\" style=\"padding:3px 8px;font-size:10px;color:var(--good);border-color:var(--good);animation-delay:0.52s\">VT</span><span class=\"fp-token pr-bob\" style=\"padding:3px 8px;font-size:10px;color:var(--good);border-color:var(--good);animation-delay:0.65s\">VT</span><span class=\"fp-token pr-bob\" style=\"padding:3px 8px;font-size:10px;color:var(--good);border-color:var(--good);animation-delay:0.78s\">VT</span><span class=\"fp-token pr-bob\" style=\"padding:3px 8px;font-size:10px;color:var(--good);border-color:var(--good);animation-delay:0.91s\">VT</span><span class=\"fp-token pr-bob\" style=\"padding:3px 8px;font-size:10px;color:var(--good);border-color:var(--good);animation-delay:1.04s\">VT</span><span class=\"fp-token pr-bob\" style=\"padding:3px 8px;font-size:10px;color:var(--good);border-color:var(--good);animation-delay:1.17s\">VT</span><span class=\"fp-token pr-bob\" style=\"padding:3px 8px;font-size:10px;color:var(--good);border-color:var(--good);animation-delay:1.30s\">VT</span><span class=\"fp-tag mut\" style=\"color:var(--mut)\">…</span></div><div class=\"fp-row\" style=\"gap:26px\"><span class=\"fp-arrow pr-flow\" style=\"color:var(--acc)\">&darr;</span><span style=\"font:10px var(--mono);color:var(--mut)\">mount()</span><span class=\"fp-arrow pr-flow\" style=\"color:var(--acc);animation-delay:.3s\">&darr;</span></div><div class=\"fp-box\" style=\"position:relative;width:100%;max-width:600px;box-sizing:border-box;border-color:var(--acc);display:flex;gap:14px;justify-content:center;flex-wrap:wrap;padding:24px 16px 16px\"><span class=\"fp-tag\" style=\"position:absolute;top:-10px;left:14px;background:var(--panel);color:var(--acc)\">несущие потоки &middot; ForkJoinPool, по числу ядер</span><div class=\"fp-col\" style=\"gap:5px;align-items:center\"><div class=\"fp-node acc fp-pulse-a\" style=\"width:auto;height:38px;min-width:78px;border-radius:19px;font-size:10px;padding:0 12px;white-space:nowrap\">carrier-1</div><span class=\"fp-token\" style=\"padding:2px 7px;font-size:9px;color:var(--good);border-color:var(--good)\">VT #418</span></div><div class=\"fp-col\" style=\"gap:5px;align-items:center\"><div class=\"fp-node acc fp-pulse-a\" style=\"width:auto;height:38px;min-width:78px;border-radius:19px;font-size:10px;padding:0 12px;white-space:nowrap;animation-delay:.4s\">carrier-2</div><span class=\"fp-token\" style=\"padding:2px 7px;font-size:9px;color:var(--good);border-color:var(--good)\">VT #77</span></div><div class=\"fp-col\" style=\"gap:5px;align-items:center\"><div class=\"fp-node acc fp-pulse-a\" style=\"width:auto;height:38px;min-width:78px;border-radius:19px;font-size:10px;padding:0 12px;white-space:nowrap;animation-delay:.8s\">carrier-3</div><span class=\"fp-token pr-blink\" style=\"padding:2px 7px;font-size:9px;color:var(--mut);border-style:dashed\">свободен</span></div><div class=\"fp-col\" style=\"gap:5px;align-items:center\"><div class=\"fp-node fp-pulse-r\" style=\"width:auto;height:38px;min-width:78px;border-radius:19px;font-size:10px;padding:0 12px;white-space:nowrap;border-color:var(--bad);color:var(--bad)\">carrier-4</div><span class=\"fp-token fp-pulse-r\" style=\"padding:2px 7px;font-size:9px;color:var(--bad);border-color:var(--bad)\">&#128274; закреплён</span></div></div><div class=\"fp-row\" style=\"gap:18px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:7px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:270px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good);white-space:nowrap\">блокирующий вызов</span><div class=\"fp-row\" style=\"gap:7px\"><span class=\"fp-token\" style=\"font-size:9px;padding:2px 7px\">socket.read()</span><span class=\"fp-arrow pr-flow\" style=\"color:var(--good)\">&rarr;</span><div class=\"fp-box good pr-glow\" style=\"font-size:10px;padding:6px 9px\">unmount</div></div><div class=\"fp-row\" style=\"gap:6px;align-items:center\"><span class=\"pr-rise\" style=\"color:var(--good);font-size:12px\">&uarr;</span><span style=\"font:9px var(--mono);color:var(--mut)\">стек VT переезжает в кучу</span></div><span style=\"font:10px var(--mono);color:var(--good);text-align:center\">несущий свободен &mdash; берёт следующий VT</span></div><div class=\"fp-col\" style=\"gap:7px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:270px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad);white-space:nowrap\">закреп (pinning)</span><div class=\"fp-row\" style=\"gap:7px\"><span class=\"fp-token\" style=\"font-size:9px;padding:2px 7px;color:var(--bad);border-color:var(--bad)\">native / JNI кадр</span><span class=\"fp-arrow pr-blink\" style=\"color:var(--bad)\">&rarr;</span><div class=\"fp-box bad fp-pulse-r\" style=\"font-size:10px;padding:6px 9px\">&#10005; unmount нельзя</div></div><div class=\"fp-row\" style=\"gap:6px;align-items:center\"><span class=\"pr-scale\" style=\"color:var(--bad);font-size:12px\">&#9889;</span><span style=\"font:9px var(--mono);color:var(--mut)\">несущий заблокирован вместе с VT</span></div><span style=\"font:10px var(--mono);color:var(--bad);text-align:center\">ядер 8 &mdash; хватит 8 закрепов, чтобы встало всё</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">поток стал <span style=\"color:var(--txt)\">объектом в куче</span>, а не системным ресурсом: их можно миллион. до JDK&nbsp;21 закреп давал и <span style=\"color:var(--bad)\">synchronized</span> &mdash; в 24 это убрали (JEP&nbsp;491), остались native-кадры</div></div>"
 },
 {
  "id": "pr-dirty-checking",
  "t": "Spring",
  "title": "Dirty checking и flush",
  "what": "Hibernate держит снимок сущности с момента загрузки и перед commit сверяет с ним текущее состояние — UPDATE рождается из разницы, а не из вызова save().",
  "html": "<div style=\"position:relative;min-height:320px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-box\" style=\"position:relative;width:100%;max-width:620px;box-sizing:border-box;border-color:var(--acc);display:flex;flex-direction:column;gap:14px;padding:24px 18px 16px\"><span class=\"fp-tag\" style=\"position:absolute;top:-10px;left:14px;background:var(--panel);color:var(--acc)\">persistence context &middot; живёт ровно столько, сколько транзакция</span><div class=\"fp-row\" style=\"justify-content:center;gap:12px;align-items:center;flex-wrap:wrap\"><span class=\"fp-token\" style=\"font-size:10px;padding:3px 9px\">find(id)</span><span class=\"fp-arrow pr-flow\" style=\"color:var(--acc)\">&rarr;</span><div class=\"fp-col\" style=\"gap:4px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--acc)\">managed</span><div class=\"fp-box acc\" style=\"font-size:10px;padding:8px 11px\">Order<br>status=<b>NEW</b></div></div><span class=\"fp-arrow\" style=\"color:var(--mut);font-size:15px\">&#8801;</span><div class=\"fp-col\" style=\"gap:4px;align-items:center\"><span class=\"fp-tag mut\" style=\"color:var(--mut)\">снимок при загрузке</span><div class=\"fp-box mut\" style=\"font-size:10px;padding:8px 11px\">Order&#39;<br>status=<b>NEW</b></div></div></div><div class=\"fp-row\" style=\"justify-content:center;gap:10px;align-items:center;flex-wrap:wrap\"><span class=\"fp-token pr-pulse\" style=\"font-size:10px;padding:3px 9px;color:var(--good);border-color:var(--good)\">order.setStatus(&laquo;PAID&raquo;)</span><span class=\"fp-arrow pr-flow\" style=\"color:var(--good);animation-delay:.4s\">&rarr;</span><div class=\"fp-box good pr-glow\" style=\"font-size:10px;padding:8px 11px;animation-delay:.5s\">Order<br>status=<b>PAID</b></div><span class=\"fp-tag mut\" style=\"color:var(--mut);text-decoration:line-through\">save()</span><span style=\"font:9px var(--mono);color:var(--mut)\">вызывать не нужно</span></div><div class=\"fp-row\" style=\"justify-content:center;gap:10px;align-items:center;flex-wrap:wrap\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">flush перед commit и перед JPQL</span><span class=\"fp-arrow pr-blink\" style=\"color:var(--warn);animation-delay:.8s\">&rarr;</span><div class=\"fp-row\" style=\"gap:5px;align-items:center;padding:5px 9px;border:1px dashed var(--line);border-radius:10px\"><span style=\"font:9px var(--mono);color:var(--good)\">PAID</span><span style=\"font:11px var(--mono);color:var(--bad)\">&#8800;</span><span style=\"font:9px var(--mono);color:var(--mut)\">NEW</span><span style=\"font:9px var(--mono);color:var(--txt)\">&nbsp;поле за полем</span></div><span class=\"fp-arrow pr-flow\" style=\"color:var(--acc);animation-delay:1s\">&rarr;</span><div class=\"fp-box acc fp-pulse-a\" style=\"font-size:10px;padding:8px 11px;animation-delay:1.1s\">UPDATE orders<br>SET status=?</div></div></div><div class=\"fp-row\" style=\"gap:16px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:11px 14px;border:1px solid var(--bad);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad);white-space:nowrap\">правка уедет в БД сама</span><span style=\"font:10px var(--mono);color:var(--mut);text-align:center\">поправил поле «для расчёта» внутри транзакции &mdash; flush сам сделает UPDATE</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:11px 14px;border:1px solid var(--warn);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn);white-space:nowrap\">detached &mdash; тишина</span><span style=\"font:10px var(--mono);color:var(--mut);text-align:center\">транзакция закрылась &mdash; тот же сеттер не делает ничего, нужен merge()</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">снимок стоит памяти: <span style=\"color:var(--txt)\">каждая managed-сущность хранится дважды</span>. выгрузил 100k строк в одну транзакцию &mdash; получил OOM на ровном месте</div></div>"
 },
 {
  "id": "pr-equals-hashcode",
  "t": "Java",
  "title": "Контракт equals и hashCode",
  "what": "Равные объекты обязаны давать одинаковый хеш: иначе HashMap ищет их в разных бакетах и до equals дело не доходит.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:16px;align-items:flex-start;flex-wrap:wrap;justify-content:center;flex-wrap:nowrap\"><div class=\"fp-col\" style=\"gap:8px;align-items:center;padding:13px 15px;border:1px solid var(--good);border-radius:12px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">переопределены оба</span><div class=\"fp-row\" style=\"gap:7px\"><div class=\"fp-box good\" style=\"font-size:10px\">a<br>«ABC»</div><span style=\"font:11px var(--mono);color:var(--good)\">=</span><div class=\"fp-box good\" style=\"font-size:10px\">b<br>«ABC»</div></div><div class=\"fp-row\" style=\"gap:6px\"><span style=\"font:9px var(--mono);color:var(--mut)\">hash</span><div class=\"fp-box good\" style=\"font-size:10px;padding:5px 8px\">42</div><span class=\"fp-arrow\" style=\"color:var(--good)\">&rarr;</span><div class=\"fp-node good\" style=\"font-size:9px\">бакет<br>2</div></div><div class=\"fp-row\" style=\"gap:6px\"><span style=\"font:9px var(--mono);color:var(--mut)\">hash</span><div class=\"fp-box good\" style=\"font-size:10px;padding:5px 8px\">42</div><span class=\"fp-arrow\" style=\"color:var(--good)\">&rarr;</span><div class=\"fp-node good fp-pulse-g\" style=\"font-size:9px\">тот же<br>бакет</div></div><span style=\"font:10px var(--mono);color:var(--good);text-align:center\">там сравнит equals &mdash; найдёт</span></div><div class=\"fp-col\" style=\"gap:8px;align-items:center;padding:13px 15px;border:1px solid var(--bad);border-radius:12px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">equals есть, hashCode забыт</span><div class=\"fp-row\" style=\"gap:7px\"><div class=\"fp-box\" style=\"font-size:10px\">a<br>«ABC»</div><span style=\"font:11px var(--mono);color:var(--good)\">=</span><div class=\"fp-box\" style=\"font-size:10px\">b<br>«ABC»</div></div><div class=\"fp-row\" style=\"gap:6px\"><span style=\"font:9px var(--mono);color:var(--mut)\">hash</span><div class=\"fp-box acc\" style=\"font-size:10px;padding:5px 8px\">42</div><span class=\"fp-arrow\" style=\"color:var(--acc)\">&rarr;</span><div class=\"fp-node acc\" style=\"font-size:9px\">бакет<br>2</div></div><div class=\"fp-row\" style=\"gap:6px\"><span style=\"font:9px var(--mono);color:var(--mut)\">hash</span><div class=\"fp-box bad\" style=\"font-size:10px;padding:5px 8px\">907</div><span class=\"fp-arrow fp-blink\" style=\"color:var(--bad)\">&rarr;</span><div class=\"fp-node bad fp-pulse-r\" style=\"font-size:9px\">бакет<br>7</div></div><span style=\"font:10px var(--mono);color:var(--bad);text-align:center\">equals никто не спросит &mdash; get вернёт null</span></div></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:wrap;justify-content:center\"><span class=\"fp-token\" style=\"font-size:10px\">равны по equals</span><span class=\"fp-arrow\" style=\"color:var(--acc)\">&rarr;</span><span class=\"fp-token\" style=\"font-size:10px;color:var(--good);border-color:var(--good)\">хеши ОБЯЗАНЫ совпасть</span><span style=\"font:14px;color:var(--mut)\">&nbsp;|&nbsp;</span><span class=\"fp-token\" style=\"font-size:10px\">хеши совпали</span><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><span class=\"fp-token mut\" style=\"font-size:10px\">равенство НЕ обязано</span></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">обратное неверно: одинаковый хеш у разных объектов &mdash; это <span style=\"color:var(--txt)\">коллизия</span>, норма. ломается наоборот: <span style=\"color:var(--bad)\">равные объекты с разными хешами</span> теряются в HashMap и HashSet</div></div>"
 },
 {
  "id": "pr-stream-lazy",
  "t": "Java",
  "title": "Стрим: ленивый конвейер",
  "what": "Промежуточные операции ничего не делают до терминальной, а потом элементы идут по одному через всю цепочку — не слоями.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-box\" style=\"position:relative;width:100%;max-width:600px;box-sizing:border-box;border-color:var(--mut);display:flex;flex-direction:column;gap:12px;padding:24px 16px 15px\"><span class=\"fp-tag\" style=\"position:absolute;top:-10px;left:14px;background:var(--panel);color:var(--mut)\">без терминальной операции не выполнится НИЧЕГО</span><div class=\"fp-row\" style=\"justify-content:center;gap:9px;flex-wrap:wrap\"><div class=\"fp-box mut\" style=\"font-size:10px\">filter</div><span class=\"fp-arrow mut\">&rarr;</span><div class=\"fp-box mut\" style=\"font-size:10px\">map</div><span class=\"fp-arrow mut\">&rarr;</span><div class=\"fp-box mut\" style=\"font-size:10px\">limit(2)</div><span class=\"fp-tag mut\" style=\"color:var(--mut)\">только описание</span></div></div><div class=\"fp-row\" style=\"gap:10px;align-items:center\"><span class=\"fp-token\" style=\"color:var(--acc);border-color:var(--acc)\">collect()</span><span style=\"font:10px var(--mono);color:var(--mut)\">&mdash; вот теперь пошло, и по ОДНОМУ элементу через всю цепочку</span></div><div class=\"fp-col\" style=\"gap:7px;align-items:stretch;width:100%;max-width:600px\"><div class=\"fp-row\" style=\"gap:8px;align-items:center;justify-content:flex-start;padding:5px 10px;border:1px solid var(--line);border-radius:10px\"><div class=\"fp-box mut\" style=\"font-size:10px;padding:5px 9px;min-width:34px\">1</div><span class=\"fp-arrow\" style=\"color:var(--mut);font-size:15px\">&rarr;</span><span style=\"font:9px var(--mono);color:var(--mut);min-width:74px\">filter отсеян</span><span style=\"font:9px var(--mono);color:var(--mut)\">дальше не пошёл &mdash; map его не видел</span></div><div class=\"fp-row\" style=\"gap:8px;align-items:center;justify-content:flex-start;padding:5px 10px;border:1px solid var(--good);border-radius:10px\"><div class=\"fp-box good\" style=\"font-size:10px;padding:5px 9px;min-width:34px\">2</div><span class=\"fp-arrow\" style=\"color:var(--good);font-size:15px\">&rarr;</span><span style=\"font:9px var(--mono);color:var(--good);min-width:74px\">filter прошёл</span><span class=\"fp-arrow\" style=\"color:var(--good);font-size:15px\">&rarr;</span><span style=\"font:9px var(--mono);color:var(--good);min-width:60px\">map &times;10</span><div class=\"fp-box good\" style=\"font-size:10px;padding:5px 9px\">20</div></div><div class=\"fp-row\" style=\"gap:8px;align-items:center;justify-content:flex-start;padding:5px 10px;border:1px solid var(--line);border-radius:10px\"><div class=\"fp-box mut\" style=\"font-size:10px;padding:5px 9px;min-width:34px\">3</div><span class=\"fp-arrow\" style=\"color:var(--mut);font-size:15px\">&rarr;</span><span style=\"font:9px var(--mono);color:var(--mut);min-width:74px\">filter отсеян</span><span style=\"font:9px var(--mono);color:var(--mut)\">дальше не пошёл &mdash; map его не видел</span></div><div class=\"fp-row\" style=\"gap:8px;align-items:center;justify-content:flex-start;padding:5px 10px;border:1px solid var(--good);border-radius:10px\"><div class=\"fp-box good\" style=\"font-size:10px;padding:5px 9px;min-width:34px\">4</div><span class=\"fp-arrow\" style=\"color:var(--good);font-size:15px\">&rarr;</span><span style=\"font:9px var(--mono);color:var(--good);min-width:74px\">filter прошёл</span><span class=\"fp-arrow\" style=\"color:var(--good);font-size:15px\">&rarr;</span><span style=\"font:9px var(--mono);color:var(--good);min-width:60px\">map &times;10</span><div class=\"fp-box good\" style=\"font-size:10px;padding:5px 9px\">40</div></div></div><div class=\"fp-row\" style=\"gap:8px;align-items:center\"><div class=\"fp-box acc fp-pulse-a\" style=\"font-size:10px\">limit(2) набран</div><span class=\"fp-arrow\" style=\"color:var(--bad)\">&rarr;</span><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">источник больше не читается</span></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">элементы идут <span style=\"color:var(--txt)\">вертикально</span>, а не слоями: не «сначала весь filter, потом весь map». поэтому map отработал <span style=\"color:var(--txt)\">2 раза</span>, а не 4, и бесконечный поток с limit не зависает</div></div>"
 },
 {
  "id": "pr-try-with-resources",
  "t": "Java",
  "title": "try-with-resources",
  "what": "Ресурсы закрываются в обратном порядке и закрываются все; исключение тела остаётся главным, сбой закрытия цепляется как suppressed.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:20px;align-items:flex-start;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:9px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--acc);border-color:var(--acc)\">открытие &mdash; сверху вниз</span><div class=\"fp-box acc\" style=\"font-size:10px\">① open A</div><span class=\"fp-arrow\" style=\"color:var(--acc)\">&darr;</span><div class=\"fp-box acc\" style=\"font-size:10px\">② open B</div><span class=\"fp-arrow\" style=\"color:var(--acc)\">&darr;</span><div class=\"fp-box\" style=\"font-size:10px;border-color:var(--warn);color:var(--warn)\">тело: бросило</div></div><div class=\"fp-col\" style=\"gap:9px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">закрытие &mdash; в ОБРАТНОМ порядке</span><div class=\"fp-box good\" style=\"font-size:10px\">③ close B</div><span class=\"fp-arrow\" style=\"color:var(--good)\">&darr;</span><div class=\"fp-box good\" style=\"font-size:10px\">④ close A</div><span class=\"fp-arrow\" style=\"color:var(--good)\">&darr;</span><span style=\"font:10px var(--mono);color:var(--good);text-align:center\">закроются оба,<br>даже если бросил close B</span></div></div><div class=\"fp-row\" style=\"gap:12px;align-items:center;flex-wrap:wrap;justify-content:center;padding:11px 14px;border:1px solid var(--warn);border-radius:12px\"><div class=\"fp-col\" style=\"gap:4px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">наружу летит</span><div class=\"fp-box\" style=\"font-size:10px;border-color:var(--warn);color:var(--warn)\">исключение ТЕЛА</div></div><span class=\"fp-arrow\" style=\"color:var(--mut)\">+</span><div class=\"fp-col\" style=\"gap:4px;align-items:center\"><span class=\"fp-tag mut\" style=\"color:var(--mut)\">прицепом</span><div class=\"fp-box mut\" style=\"font-size:10px\">исключение close<br>getSuppressed()</div></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">без try-with-resources писали <span style=\"color:var(--bad)\">finally { close() }</span> &mdash; и если close тоже бросал, он <span style=\"color:var(--bad)\">затирал настоящую причину</span>. здесь причина остаётся главной, а сбой закрытия висит рядом</div></div>"
 },
 {
  "id": "pr-bean-lifecycle",
  "t": "Spring",
  "title": "Жизненный цикл бина",
  "what": "Скан → конструктор → внедрение полей → @PostConstruct → обёртка в прокси. Из конструктора прокси ещё нет, а поля @Value ещё пустые.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:7px;align-items:center;flex-wrap:wrap;justify-content:center;max-width:640px;flex-wrap:nowrap\"><div class=\"fp-col\" style=\"gap:4px;align-items:center;max-width:96px\"><div class=\"fp-box\" style=\"font-size:9.5px;padding:6px 8px;border-color:var(--mut);color:var(--mut)\">скан</div><span style=\"font:8.5px var(--mono);color:var(--mut);text-align:center\">нашёл @Component</span></div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-col\" style=\"gap:4px;align-items:center;max-width:96px\"><div class=\"fp-box\" style=\"font-size:9.5px;padding:6px 8px;border-color:var(--acc);color:var(--acc)\">конструктор</div><span style=\"font:8.5px var(--mono);color:var(--mut);text-align:center\">обязательные зависимости</span></div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-col\" style=\"gap:4px;align-items:center;max-width:96px\"><div class=\"fp-box\" style=\"font-size:9.5px;padding:6px 8px;border-color:var(--acc);color:var(--acc)\">поля и сеттеры</div><span style=\"font:8.5px var(--mono);color:var(--mut);text-align:center\">@Autowired</span></div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-col\" style=\"gap:4px;align-items:center;max-width:96px\"><div class=\"fp-box\" style=\"font-size:9.5px;padding:6px 8px;border-color:var(--good);color:var(--good)\">@PostConstruct</div><span style=\"font:8.5px var(--mono);color:var(--mut);text-align:center\">всё внедрено</span></div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-col\" style=\"gap:4px;align-items:center;max-width:96px\"><div class=\"fp-box\" style=\"font-size:9.5px;padding:6px 8px;border-color:var(--warn);color:var(--warn)\">обёртка в прокси</div><span style=\"font:8.5px var(--mono);color:var(--mut);text-align:center\">@Transactional, @Cacheable</span></div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-col\" style=\"gap:4px;align-items:center;max-width:96px\"><div class=\"fp-box\" style=\"font-size:9.5px;padding:6px 8px;border-color:var(--good);color:var(--good)\">готов</div><span style=\"font:8.5px var(--mono);color:var(--mut);text-align:center\">в контейнере</span></div></div><div class=\"fp-row\" style=\"gap:16px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:268px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">в конструкторе прокси ещё НЕТ</span><div class=\"fp-box bad\" style=\"font-size:10px\">this.save() из конструктора<br>&rarr; мимо транзакции</div><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">обёртка появляется на шаге 5, после @PostConstruct</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--warn);border-radius:12px;max-width:268px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">@PostConstruct вместо конструктора</span><div class=\"fp-box\" style=\"font-size:10px;border-color:var(--warn);color:var(--warn)\">поля @Value уже заполнены<br>зависимости внедрены</div><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">в конструкторе они ещё null</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">порядок между бинами контейнер выводит из графа зависимостей, а не из порядка файлов. <span style=\"color:var(--txt)\">@DependsOn</span> нужен только там, где связи в графе нет, а порядок важен</div></div>"
 },
 {
  "id": "pr-security-chain",
  "t": "Spring",
  "title": "Цепочка фильтров Security",
  "what": "Фильтры срабатывают до DispatcherServlet: отказ отдаёт 401/403, и в логах контроллера при этом пусто.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:6px;align-items:center;flex-wrap:wrap;justify-content:center;max-width:660px;flex-wrap:nowrap\"><span class=\"fp-token\" style=\"font-size:10px\">запрос</span><span class=\"fp-arrow\" style=\"color:var(--acc)\">&rarr;</span><div class=\"fp-box\" style=\"font-size:9px;padding:6px 8px;border-color:var(--mut);color:var(--mut)\">SecurityContext<br>Holder</div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-box\" style=\"font-size:9px;padding:6px 8px;border-color:var(--acc);color:var(--acc)\">BearerToken<br>Authentication</div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-box\" style=\"font-size:9px;padding:6px 8px;border-color:var(--acc);color:var(--acc)\">Authorization<br>Filter</div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-box acc fp-pulse-a\" style=\"font-size:9.5px\">Dispatcher<br>Servlet</div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-box\" style=\"font-size:9.5px\">@RestController</div></div><div class=\"fp-row\" style=\"gap:12px;align-items:center;flex-wrap:wrap;justify-content:center\"><div class=\"fp-box bad fp-pulse-r\" style=\"font-size:10px\">401 / 403 отсюда</div><span class=\"fp-arrow\" style=\"color:var(--bad)\">&rarr;</span><span style=\"font:10px var(--mono);color:var(--bad)\">до контроллера не дошло &mdash; в его логах ПУСТО</span></div><div class=\"fp-row\" style=\"gap:14px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:11px 13px;border:1px solid var(--warn);border-radius:12px;max-width:272px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">@ControllerAdvice не поможет</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">он живёт внутри DispatcherServlet, а фильтр отбил запрос раньше</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:11px 13px;border:1px solid var(--good);border-radius:12px;max-width:272px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">чинится на своём уровне</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">AuthenticationEntryPoint и AccessDeniedHandler</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">фильтры &mdash; это <span style=\"color:var(--txt)\">сервлет-уровень</span>, они старше Spring MVC. оттого и CORS настраивают в Security, а не аннотацией на контроллере</div></div>"
 },
 {
  "id": "pr-n-plus-one",
  "t": "Spring",
  "title": "N+1 запрос",
  "what": "Один запрос списка плюс по запросу на каждую ленивую связь: на десяти строках незаметно, на сотне — сто лишних round-trip.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:18px;align-items:flex-start;flex-wrap:wrap;justify-content:center;flex-wrap:nowrap\"><div class=\"fp-col\" style=\"gap:8px;align-items:center;padding:13px 15px;border:1px solid var(--bad);border-radius:12px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">ленивая связь в цикле</span><div class=\"fp-box acc\" style=\"font-size:10px\">① SELECT * FROM orders</div><span style=\"font:9px var(--mono);color:var(--mut)\">вернул 100 строк</span><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-box bad\" style=\"font-size:9.5px;padding:4px 8px\">SELECT items WHERE order_id=1</div><div class=\"fp-box bad\" style=\"font-size:9.5px;padding:4px 8px\">SELECT items WHERE order_id=2</div><div class=\"fp-box bad\" style=\"font-size:9.5px;padding:4px 8px\">SELECT items WHERE order_id=3</div><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">&hellip; и так 100 раз</span></div><div class=\"fp-row\" style=\"gap:6px;align-items:center\"><span class=\"fp-val\" style=\"font-size:22px\">101</span><span style=\"font:10px var(--mono);color:var(--bad)\">запрос<br>вместо одного</span></div></div><div class=\"fp-col\" style=\"gap:8px;align-items:center;padding:13px 15px;border:1px solid var(--good);border-radius:12px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">join fetch</span><div class=\"fp-box good\" style=\"font-size:10px\">SELECT o, i<br>FROM Order o<br>JOIN FETCH o.items</div><span class=\"fp-arrow\" style=\"color:var(--good)\">&darr;</span><div class=\"fp-row\" style=\"gap:6px;align-items:center\"><span class=\"fp-val\" style=\"font-size:22px\">1</span><span style=\"font:10px var(--mono);color:var(--good)\">запрос</span></div><span style=\"font:9px var(--mono);color:var(--mut);text-align:center\">или @EntityGraph,<br>или batch-size</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">на демо-данных из десяти строк <span style=\"color:var(--txt)\">незаметно</span>: 11 быстрых запросов вместо одного. на проде это 101 сетевой round-trip, и время растёт линейно от размера списка</div></div>"
 },
 {
  "id": "pr-saga",
  "t": "Distributed",
  "title": "Saga и компенсации",
  "what": "Шаги коммитятся по одному; упал третий — предыдущие отменяются компенсирующими операциями, а не откатом.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:6px;align-items:center;flex-wrap:wrap;justify-content:center;flex-wrap:nowrap\"><div class=\"fp-col\" style=\"gap:4px;align-items:center\"><div class=\"fp-box\" style=\"font-size:9.5px;border-color:var(--good);color:var(--good)\">резерв<br>товара</div><span style=\"font:12px;color:var(--good)\">✓</span></div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-col\" style=\"gap:4px;align-items:center\"><div class=\"fp-box\" style=\"font-size:9.5px;border-color:var(--good);color:var(--good)\">списание<br>денег</div><span style=\"font:12px;color:var(--good)\">✓</span></div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-col\" style=\"gap:4px;align-items:center\"><div class=\"fp-box\" style=\"font-size:9.5px;border-color:var(--bad);color:var(--bad)\">бронь<br>доставки</div><span style=\"font:12px;color:var(--bad)\">✗</span></div></div><div class=\"fp-row\" style=\"gap:8px;align-items:center\"><span class=\"pr-rise\" style=\"color:var(--bad);font-size:14px\">&uarr;</span><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">третий шаг упал &mdash; отката транзакции тут нет</span></div><div class=\"fp-row\" style=\"gap:6px;align-items:center;flex-wrap:wrap;justify-content:center;padding:12px 14px;border:1px solid var(--warn);border-radius:12px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">компенсации, в обратном порядке</span><div class=\"fp-box\" style=\"font-size:9.5px;border-color:var(--warn);color:var(--warn)\">вернуть<br>деньги</div><span class=\"fp-arrow\" style=\"color:var(--warn)\">&rarr;</span><div class=\"fp-box\" style=\"font-size:9.5px;border-color:var(--warn);color:var(--warn)\">снять<br>резерв</div></div><div class=\"fp-row\" style=\"gap:14px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:5px;align-items:center;padding:10px 13px;border:1px dashed var(--line);border-radius:11px;max-width:250px\"><span class=\"fp-tag mut\" style=\"color:var(--mut)\">это не откат</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">деньги успели уйти и вернуться &mdash; в выписке две операции</span></div><div class=\"fp-col\" style=\"gap:5px;align-items:center;padding:10px 13px;border:1px dashed var(--line);border-radius:11px;max-width:250px\"><span class=\"fp-tag mut\" style=\"color:var(--mut)\">компенсация может упасть</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">её нужно ретраить и делать идемпотентной</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">между шагами система <span style=\"color:var(--bad)\">видна снаружи наполовину выполненной</span> &mdash; это и есть цена отказа от распределённой транзакции</div></div>"
 },
 {
  "id": "pr-test-doubles",
  "t": "Testing",
  "title": "Stub, mock, spy",
  "what": "Stub отдаёт заготовленный ответ и проверяет результат, mock запоминает вызовы и проверяет взаимодействие, spy — настоящий объект с подменённым методом.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:14px;align-items:stretch;flex-wrap:wrap;justify-content:center;flex-wrap:nowrap\"><div class=\"fp-col\" style=\"gap:8px;align-items:center;padding:13px 15px;border:1px solid var(--acc);border-radius:12px;max-width:210px\"><span class=\"fp-tag\" style=\"color:var(--acc);border-color:var(--acc)\">stub</span><div class=\"fp-box acc\" style=\"font-size:10px\">отдаёт<br>заготовленное</div><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">проверяем РЕЗУЛЬТАТ: что вернул наш код</span><div class=\"fp-box mut\" style=\"font-size:9px\">assertEquals(...)</div></div><div class=\"fp-col\" style=\"gap:8px;align-items:center;padding:13px 15px;border:1px solid var(--warn);border-radius:12px;max-width:210px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">mock</span><div class=\"fp-box\" style=\"font-size:10px;border-color:var(--warn);color:var(--warn)\">запоминает<br>вызовы</div><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">проверяем ВЗАИМОДЕЙСТВИЕ: кого позвали и с чем</span><div class=\"fp-box mut\" style=\"font-size:9px\">verify(sender).send(x)</div></div><div class=\"fp-col\" style=\"gap:8px;align-items:center;padding:13px 15px;border:1px solid var(--good);border-radius:12px;max-width:210px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">spy</span><div class=\"fp-box good\" style=\"font-size:10px\">настоящий объект<br>+ подглядывание</div><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">логика реальная, подменён один метод</span><div class=\"fp-box mut\" style=\"font-size:9px\">doReturn(..).when(spy)</div></div></div><div class=\"fp-row\" style=\"gap:10px;align-items:center;flex-wrap:wrap;justify-content:center\"><span class=\"fp-token\" style=\"font-size:10px;color:var(--bad);border-color:var(--bad)\">чем больше verify</span><span class=\"fp-arrow\" style=\"color:var(--bad)\">&rarr;</span><span style=\"font:10px var(--mono);color:var(--bad)\">тем сильнее тест прибит к РЕАЛИЗАЦИИ</span></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">mock ломается при рефакторинге, который ничего не сломал: поменял порядок вызовов &mdash; тест красный, поведение то же. проверяй взаимодействие только там, где сам вызов и есть результат &mdash; отправка письма, запись в очередь</div></div>"
 },
 {
  "id": "pr-docker-layers",
  "t": "DevOps",
  "title": "Слои образа и кэш сборки",
  "what": "Слой изменился — все слои ниже пересобираются. Отсюда правило: редко меняется выше, часто меняется ниже.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:20px;align-items:flex-start;flex-wrap:wrap;justify-content:center;flex-wrap:nowrap\"><div class=\"fp-col\" style=\"gap:5px;align-items:stretch\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">плохой порядок</span><div class=\"fp-box bad\" style=\"font-size:9.5px;padding:6px 10px;min-width:150px\">COPY . .</div><span class=\"fp-arrow\" style=\"color:var(--bad);text-align:center;display:block\">&darr;</span><div class=\"fp-box bad\" style=\"font-size:9.5px;padding:6px 10px;min-width:150px\">RUN mvn package</div><span style=\"font:9px var(--mono);color:var(--bad);text-align:center;margin-top:4px\">правка одной строки кода<br>&rarr; пересборка ВСЕХ зависимостей</span></div><div class=\"fp-col\" style=\"gap:5px;align-items:stretch\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">хороший порядок</span><div class=\"fp-box good\" style=\"font-size:9.5px;padding:6px 10px;min-width:150px\">COPY pom.xml</div><span class=\"fp-arrow\" style=\"color:var(--mut);text-align:center;display:block\">&darr;</span><div class=\"fp-box good\" style=\"font-size:9.5px;padding:6px 10px;min-width:150px\">RUN mvn dependency:go-offline</div><span class=\"fp-arrow\" style=\"color:var(--mut);text-align:center;display:block\">&darr;</span><div class=\"fp-box acc\" style=\"font-size:9.5px;padding:6px 10px;min-width:150px\">COPY src ./src</div><span class=\"fp-arrow\" style=\"color:var(--mut);text-align:center;display:block\">&darr;</span><div class=\"fp-box acc\" style=\"font-size:9.5px;padding:6px 10px;min-width:150px\">RUN mvn package</div><span style=\"font:9px var(--mono);color:var(--good);text-align:center;margin-top:4px\">первые два слоя взяты из кэша<br>&rarr; собирается только код</span></div></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:wrap;justify-content:center\"><span class=\"fp-tag mut\" style=\"color:var(--mut)\">правило</span><span style=\"font:10px var(--mono);color:var(--txt)\">редко меняется &mdash; выше, часто меняется &mdash; ниже</span></div><div class=\"fp-row\" style=\"gap:9px;align-items:center\"><div class=\"fp-box bad\" style=\"font-size:9.5px\">слой изменился</div><span class=\"fp-arrow\" style=\"color:var(--bad)\">&rarr;</span><span style=\"font:10px var(--mono);color:var(--bad)\">все слои НИЖЕ него пересобираются, кэш дальше не действует</span></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">поэтому <span style=\"color:var(--bad)\">COPY . .</span> первой строкой убивает кэш целиком: любой файл, включая README, меняет слой &mdash; и Maven снова тянет полсети</div></div>"
 },
 {
  "id": "pr-probes",
  "t": "DevOps",
  "title": "Liveness и readiness",
  "what": "Liveness убивает под, readiness лишь убирает его из балансировщика. Проверка БД в liveness перезапускает весь кластер разом.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:16px;align-items:stretch;flex-wrap:wrap;justify-content:center;flex-wrap:nowrap\"><div class=\"fp-col\" style=\"gap:8px;align-items:center;padding:13px 15px;border:1px solid var(--bad);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">liveness &mdash; «жив ли вообще»</span><div class=\"fp-row\" style=\"gap:6px;align-items:center\"><div class=\"fp-box bad\" style=\"font-size:10px\">не отвечает</div><span class=\"fp-arrow\" style=\"color:var(--bad)\">&rarr;</span><div class=\"fp-node bad fp-pulse-r\" style=\"font-size:9px\">убить<br>и поднять</div></div><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">лечит зависший процесс. проверять здесь зависимости НЕЛЬЗЯ</span></div><div class=\"fp-col\" style=\"gap:8px;align-items:center;padding:13px 15px;border:1px solid var(--good);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">readiness &mdash; «можно ли слать трафик»</span><div class=\"fp-row\" style=\"gap:6px;align-items:center\"><div class=\"fp-box\" style=\"font-size:10px;border-color:var(--warn);color:var(--warn)\">БД недоступна</div><span class=\"fp-arrow\" style=\"color:var(--warn)\">&rarr;</span><div class=\"fp-node\" style=\"font-size:9px;border-color:var(--warn);color:var(--warn)\">убрать<br>из балансира</div></div><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">под живёт и вернётся сам, когда зависимость поднимется</span></div></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 15px;border:1px solid var(--bad);border-radius:12px;max-width:560px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">классическая ошибка: БД в liveness</span><span style=\"font:10px var(--mono);color:var(--mut);text-align:center\">БД моргнула &rarr; все поды разом не прошли liveness &rarr; <span style=\"color:var(--bad)\">кластер перезапустил их все</span> &rarr; после старта они дружно ломятся в ту же БД</span></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">третья проба &mdash; <span style=\"color:var(--txt)\">startup</span>: пока идёт долгий старт, она держит liveness выключенной, иначе медленный прогрев выглядит как зависание и под убивают в цикле</div></div>"
 },
 {
  "id": "pr-hexagon",
  "t": "Архитектура",
  "title": "Порты и адаптеры",
  "what": "Ядро объявляет интерфейсы-порты, адаптеры их реализуют — зависимости смотрят внутрь, и ядро собирается без базы и сети.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:12px;align-items:center;flex-wrap:wrap;justify-content:center;flex-wrap:nowrap\"><div class=\"fp-col\" style=\"gap:6px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--acc);border-color:var(--acc)\">ведущие адаптеры</span><div class=\"fp-box acc\" style=\"font-size:9.5px;padding:5px 10px\">REST</div><div class=\"fp-box acc\" style=\"font-size:9.5px;padding:5px 10px\">Kafka</div><div class=\"fp-box acc\" style=\"font-size:9.5px;padding:5px 10px\">CLI</div></div><span class=\"fp-arrow\" style=\"color:var(--acc);font-size:20px\">&rarr;</span><div class=\"fp-col\" style=\"gap:5px;align-items:center;padding:14px 16px;border:2px solid var(--good);border-radius:14px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">ядро</span><div class=\"fp-box good\" style=\"font-size:10px\">домен<br>+ сценарии</div><span style=\"font:9px var(--mono);color:var(--good);text-align:center\">не знает ни про HTTP,<br>ни про SQL</span></div><span class=\"fp-arrow\" style=\"color:var(--warn);font-size:20px\">&rarr;</span><div class=\"fp-col\" style=\"gap:6px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">ведомые адаптеры</span><div class=\"fp-box\" style=\"font-size:9.5px;padding:5px 10px;border-color:var(--warn);color:var(--warn)\">Postgres</div><div class=\"fp-box\" style=\"font-size:9.5px;padding:5px 10px;border-color:var(--warn);color:var(--warn)\">S3</div><div class=\"fp-box\" style=\"font-size:9.5px;padding:5px 10px;border-color:var(--warn);color:var(--warn)\">SMTP</div></div></div><div class=\"fp-row\" style=\"gap:10px;align-items:center;flex-wrap:wrap;justify-content:center\"><span class=\"fp-token\" style=\"font-size:10px;color:var(--good);border-color:var(--good)\">порт = интерфейс, объявленный ЯДРОМ</span><span style=\"font:10px var(--mono);color:var(--mut)\">адаптер его реализует, зависимость смотрит внутрь</span></div><div class=\"fp-row\" style=\"gap:14px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">признак, что гексагон настоящий</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">подменил Postgres на память &mdash; ядро и его тесты не изменились ни на строку</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">признак, что это слои с новыми именами</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">в ядре импортируется @Entity, Row, HttpServletRequest</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">смысл не в числе папок, а в направлении зависимостей: <span style=\"color:var(--txt)\">внутрь</span>. ядро можно собрать и протестировать без базы, брокера и сети</div></div>"
 },
 {
  "id": "pr-deadlock-db",
  "t": "DB",
  "title": "Дедлок двух транзакций",
  "what": "Две транзакции берут одни строки в разном порядке и ждут друг друга; СУБД видит цикл и убивает одну из них.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:22px;align-items:flex-start;flex-wrap:wrap;justify-content:center;flex-wrap:nowrap\"><div class=\"fp-col\" style=\"gap:7px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--acc);border-color:var(--acc)\">транзакция A</span><div class=\"fp-box acc\" style=\"font-size:10px\">① UPDATE строка 1</div><span style=\"font:9px var(--mono);color:var(--good)\">замок взят</span><div class=\"fp-box\" style=\"font-size:10px;border-color:var(--warn);color:var(--warn)\">③ UPDATE строка 2</div><span style=\"font:9px var(--mono);color:var(--warn)\">ждёт B</span></div><div class=\"fp-col\" style=\"gap:8px;align-items:center;padding-top:26px\"><span class=\"fp-arrow fp-blink\" style=\"color:var(--bad);font-size:20px\">&hArr;</span><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">круг ожидания</span></div><div class=\"fp-col\" style=\"gap:7px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--acc);border-color:var(--acc)\">транзакция B</span><div class=\"fp-box acc\" style=\"font-size:10px\">② UPDATE строка 2</div><span style=\"font:9px var(--mono);color:var(--good)\">замок взят</span><div class=\"fp-box\" style=\"font-size:10px;border-color:var(--warn);color:var(--warn)\">④ UPDATE строка 1</div><span style=\"font:9px var(--mono);color:var(--warn)\">ждёт A</span></div></div><div class=\"fp-row\" style=\"gap:10px;align-items:center\"><div class=\"fp-box bad fp-pulse-r\" style=\"font-size:10px\">СУБД видит цикл</div><span class=\"fp-arrow\" style=\"color:var(--bad)\">&rarr;</span><span style=\"font:10px var(--mono);color:var(--bad)\">убивает одну: deadlock detected, вторая идёт дальше</span></div><div class=\"fp-row\" style=\"gap:14px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">лечение</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">брать строки ВСЕГДА в одном порядке &mdash; например, по возрастанию id</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--warn);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">не лечение</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">просто ретраить: под нагрузкой два ретрая встретятся снова</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">это не зависание: СУБД разрывает круг сама за миллисекунды. приложение обязано <span style=\"color:var(--txt)\">поймать ошибку и повторить</span> &mdash; иначе пользователь увидит 500 там, где данные целы</div></div>"
 },
 {
  "id": "pr-redis-single",
  "t": "Infra",
  "title": "Redis: один поток на команды",
  "what": "Команды выполняются по одной в единственном потоке: атомарность бесплатна, но одна тяжёлая команда останавливает всех.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:10px;align-items:center;flex-wrap:wrap;justify-content:center;flex-wrap:nowrap\"><div class=\"fp-col\" style=\"gap:5px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--mut);border-color:var(--mut)\">клиенты</span><span class=\"fp-token\" style=\"font-size:9px;padding:3px 8px\">A</span><span class=\"fp-token\" style=\"font-size:9px;padding:3px 8px\">B</span><span class=\"fp-token\" style=\"font-size:9px;padding:3px 8px\">C</span><span class=\"fp-token\" style=\"font-size:9px;padding:3px 8px\">D</span></div><span class=\"fp-arrow\" style=\"color:var(--acc)\">&rarr;</span><div class=\"fp-col\" style=\"gap:4px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--acc);border-color:var(--acc)\">очередь команд</span><div class=\"fp-stack\" style=\"gap:3px\"><div class=\"fp-slot\" style=\"font-size:9px;padding:4px 10px;min-width:70px\">GET</div><div class=\"fp-slot\" style=\"font-size:9px;padding:4px 10px;min-width:70px\">SET</div><div class=\"fp-slot\" style=\"font-size:9px;padding:4px 10px;min-width:70px\">INCR</div><div class=\"fp-slot\" style=\"font-size:9px;padding:4px 10px;min-width:70px\">GET</div></div></div><span class=\"fp-arrow\" style=\"color:var(--acc)\">&rarr;</span><div class=\"fp-col\" style=\"gap:5px;align-items:center;padding:12px 14px;border:2px solid var(--good);border-radius:13px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">ОДИН поток</span><div class=\"fp-node good fp-pulse-g\" style=\"font-size:9px\">выполняет<br>по одной</div><span style=\"font:9px var(--mono);color:var(--good);text-align:center\">блокировок нет,<br>гонок нет</span></div></div><div class=\"fp-row\" style=\"gap:14px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">поэтому атомарно бесплатно</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">INCR, SETNX и вся команда целиком — никто не влезет в середину</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">поэтому одна тяжёлая команда — стоп всему</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">KEYS * или большой LRANGE держат единственный поток, остальные ждут</span></div></div><div class=\"fp-row\" style=\"gap:9px;align-items:center\"><span class=\"fp-token\" style=\"font-size:10px;color:var(--warn);border-color:var(--warn)\">SCAN вместо KEYS</span><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><span style=\"font:10px var(--mono);color:var(--mut)\">режет обход на порции и отпускает поток между ними</span></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">однопоточность &mdash; не недостаток, а причина скорости: нет переключений контекста и синхронизации. сеть и разбор команд с версии 6 живут в <span style=\"color:var(--txt)\">отдельных потоках</span>, но сами команды по-прежнему исполняет один</div></div>"
 },
 {
  "id": "pr-git-three-areas",
  "t": "Git",
  "title": "Три зоны: каталог, индекс, история",
  "what": "Почти все команды двигают файлы между рабочим каталогом, индексом и историей. Опасны лишь те, что стирают каталог — там истории нет.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:wrap;justify-content:center;flex-wrap:nowrap\"><div class=\"fp-col\" style=\"gap:5px;align-items:center;padding:12px 14px;border:1px solid var(--warn);border-radius:12px;min-width:140px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">рабочий каталог</span><span style=\"font:9px var(--mono);color:var(--mut);text-align:center\">файлы, которые ты правишь</span></div><span class=\"fp-arrow\" style=\"color:var(--mut);font-size:18px\">&rarr;</span><div class=\"fp-col\" style=\"gap:5px;align-items:center;padding:12px 14px;border:1px solid var(--acc);border-radius:12px;min-width:140px\"><span class=\"fp-tag\" style=\"color:var(--acc);border-color:var(--acc)\">индекс (stage)</span><span style=\"font:9px var(--mono);color:var(--mut);text-align:center\">что войдёт в коммит</span></div><span class=\"fp-arrow\" style=\"color:var(--mut);font-size:18px\">&rarr;</span><div class=\"fp-col\" style=\"gap:5px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;min-width:140px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">HEAD / история</span><span style=\"font:9px var(--mono);color:var(--mut);text-align:center\">что уже зафиксировано</span></div></div><div class=\"fp-row\" style=\"gap:7px;align-items:center;flex-wrap:wrap;justify-content:center\"><span class=\"fp-token\" style=\"font-size:9.5px;color:var(--acc);border-color:var(--acc)\">git add</span><span style=\"font:9px var(--mono);color:var(--mut)\">&nbsp;затем&nbsp;</span><span class=\"fp-token\" style=\"font-size:9.5px;color:var(--acc);border-color:var(--acc)\">git commit</span></div><div class=\"fp-row\" style=\"gap:12px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:238px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">git restore ФАЙЛ</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">берёт из индекса и затирает правку в рабочем каталоге</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">вернуть нечем — правка нигде не сохранена</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:238px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">git restore --staged</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">убирает из индекса, правку в файле оставляет</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">обратимо</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--warn);border-radius:12px;max-width:238px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">git commit --amend</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">переписывает последний коммит новым хешем</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">после push нужен force</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">почти все «страшные» команды двигают файлы <span style=\"color:var(--txt)\">между этими тремя зонами</span>. опасны только те, что стирают рабочий каталог: там нет истории, восстанавливать неоткуда</div></div>"
 },
 {
  "id": "pr-hash-collision",
  "t": "Algorithms",
  "title": "Коллизии в хеш-таблице",
  "what": "Равномерный хеш даёт O(1); все ключи в одном бакете вырождают поиск в O(n), поэтому длинная цепочка превращается в дерево.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:16px;align-items:flex-start;flex-wrap:wrap;justify-content:center;flex-wrap:nowrap\"><div class=\"fp-col\" style=\"gap:6px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">равномерный хеш</span><div class=\"fp-grid\" style=\"grid-auto-flow:column;gap:5px\"><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell good\"></div></div><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell good\"></div></div><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell good\"></div></div><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell good\"></div><div class=\"fp-cell good\"></div></div><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell good\"></div></div><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell good\"></div></div><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell good\"></div></div><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell good\"></div></div></div><span style=\"font:10px var(--mono);color:var(--good)\">поиск &asymp; O(1)</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">все ключи в один бакет</span><div class=\"fp-grid\" style=\"grid-auto-flow:column;gap:5px\"><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell dead\"></div></div><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell dead\"></div></div><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell bad\"></div><div class=\"fp-cell bad\"></div><div class=\"fp-cell bad\"></div><div class=\"fp-cell bad\"></div><div class=\"fp-cell bad\"></div><div class=\"fp-cell bad\"></div><div class=\"fp-cell bad\"></div><div class=\"fp-cell bad\"></div></div><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell dead\"></div></div><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell dead\"></div></div><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell dead\"></div></div><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell dead\"></div></div><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-cell dead\"></div></div></div><span style=\"font:10px var(--mono);color:var(--bad)\">поиск выродился в O(n)</span></div></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:wrap;justify-content:center\"><div class=\"fp-box bad\" style=\"font-size:9.5px\">цепочка &ge; 8</div><span class=\"fp-arrow\" style=\"color:var(--acc)\">&rarr;</span><div class=\"fp-box acc fp-pulse-a\" style=\"font-size:9.5px\">бакет становится<br>красно-чёрным деревом</div><span class=\"fp-arrow\" style=\"color:var(--good)\">&rarr;</span><div class=\"fp-box good\" style=\"font-size:9.5px\">O(log n)</div></div><div class=\"fp-row\" style=\"gap:14px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--warn);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">это предохранитель, а не оптимизация</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">при нормальном хеше цепочка длиной 8 практически не встречается</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">чтобы дерево заработало</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">ключ должен быть Comparable — иначе сравнение идёт по грязному tie-break</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">превращение в дерево спасает от <span style=\"color:var(--txt)\">атаки подобранными ключами</span>: раньше специально сделанные коллизии превращали любой разбор JSON в O(n²)</div></div>"
 },
 {
  "id": "pr-strategy",
  "t": "Design",
  "title": "Strategy вместо цепочки if",
  "what": "Варианты становятся классами за общим интерфейсом: новый способ добавляется новым классом, старый код не меняется.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:18px;align-items:flex-start;flex-wrap:wrap;justify-content:center;flex-wrap:nowrap\"><div class=\"fp-col\" style=\"gap:7px;align-items:center;padding:13px 15px;border:1px solid var(--bad);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">без стратегии</span><div class=\"fp-box bad\" style=\"font-size:9.5px;text-align:left;padding:8px 11px\">if (тип == CARD)<br>else if (тип == QR)<br>else if (тип == CASH)<br>else if &hellip;</div><span style=\"font:9.5px var(--mono);color:var(--bad);text-align:center\">новый способ оплаты &rarr; правим этот метод снова</span></div><span class=\"fp-arrow\" style=\"color:var(--mut);font-size:20px;align-self:center\">&rarr;</span><div class=\"fp-col\" style=\"gap:7px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">со стратегией</span><div class=\"fp-box acc\" style=\"font-size:9.5px\">интерфейс<br>PaymentMethod</div><span class=\"fp-arrow\" style=\"color:var(--acc)\">&darr;</span><div class=\"fp-row\" style=\"gap:6px\"><div class=\"fp-box good\" style=\"font-size:9px;padding:5px 9px\">Card</div><div class=\"fp-box good\" style=\"font-size:9px;padding:5px 9px\">QR</div><div class=\"fp-box good\" style=\"font-size:9px;padding:5px 9px\">Cash</div></div><span style=\"font:9.5px var(--mono);color:var(--good);text-align:center\">новый способ &mdash; новый класс,<br>старое не трогаем</span></div></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:wrap;justify-content:center\"><span class=\"fp-token\" style=\"font-size:10px\">в Spring это почти бесплатно</span><span class=\"fp-arrow\" style=\"color:var(--acc)\">&rarr;</span><span class=\"fp-token\" style=\"font-size:9.5px;color:var(--acc);border-color:var(--acc)\">List&lt;PaymentMethod&gt; в конструкторе</span><span style=\"font:10px var(--mono);color:var(--mut)\">&mdash; контейнер соберёт все реализации сам</span></div><div class=\"fp-row\" style=\"gap:14px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">когда оправдано</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">вариантов больше двух и они добавляются</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">каждый вариант — самостоятельная логика</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--warn);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">когда это лишний слой</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">два варианта, которые не менялись год</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">ветки по три строки — if честнее</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">это Open-Closed на практике: <span style=\"color:var(--txt)\">открыт для расширения, закрыт для изменения</span>. но за каждый интерфейс платишь прыжком по файлам &mdash; ради двух веток не стоит</div></div>"
 },
 {
  "id": "pr-password-salt",
  "t": "Crypto",
  "title": "Соль и медленный хеш",
  "what": "Соль делает одинаковые пароли разными хешами и обесценивает радужные таблицы; медленный алгоритм убивает перебор.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:16px;align-items:flex-start;flex-wrap:wrap;justify-content:center;flex-wrap:nowrap\"><div class=\"fp-col\" style=\"gap:7px;align-items:center;padding:13px 15px;border:1px solid var(--bad);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">быстрый хеш без соли</span><div class=\"fp-row\" style=\"gap:5px;align-items:center\"><div class=\"fp-box\" style=\"font-size:9px;padding:5px 8px\">qwerty</div><span class=\"fp-arrow\" style=\"color:var(--bad)\">&rarr;</span><div class=\"fp-box bad\" style=\"font-size:9px;padding:5px 8px\">65e84be&hellip;</div></div><div class=\"fp-row\" style=\"gap:5px;align-items:center\"><div class=\"fp-box\" style=\"font-size:9px;padding:5px 8px\">qwerty</div><span class=\"fp-arrow\" style=\"color:var(--bad)\">&rarr;</span><div class=\"fp-box bad\" style=\"font-size:9px;padding:5px 8px\">65e84be&hellip;</div></div><span style=\"font:9.5px var(--mono);color:var(--bad);text-align:center\">одинаковые пароли &mdash; одинаковые хеши: видно по базе, кто чем пользуется</span></div><div class=\"fp-col\" style=\"gap:7px;align-items:center;padding:13px 15px;border:1px solid var(--good);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">соль у каждого своя</span><div class=\"fp-row\" style=\"gap:5px;align-items:center\"><div class=\"fp-box\" style=\"font-size:9px;padding:5px 8px\">qwerty</div><span style=\"font:10px var(--mono);color:var(--mut)\">+</span><div class=\"fp-box acc\" style=\"font-size:9px;padding:5px 8px\">a7f2</div><span class=\"fp-arrow\" style=\"color:var(--good)\">&rarr;</span><div class=\"fp-box good\" style=\"font-size:9px;padding:5px 8px\">1c9d&hellip;</div></div><div class=\"fp-row\" style=\"gap:5px;align-items:center\"><div class=\"fp-box\" style=\"font-size:9px;padding:5px 8px\">qwerty</div><span style=\"font:10px var(--mono);color:var(--mut)\">+</span><div class=\"fp-box acc\" style=\"font-size:9px;padding:5px 8px\">3b81</div><span class=\"fp-arrow\" style=\"color:var(--good)\">&rarr;</span><div class=\"fp-box good\" style=\"font-size:9px;padding:5px 8px\">e40a&hellip;</div></div><span style=\"font:9.5px var(--mono);color:var(--good);text-align:center\">радужная таблица бесполезна: её пришлось бы строить под каждую соль</span></div></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:wrap;justify-content:center\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">соль &mdash; только половина дела</span><div class=\"fp-box\" style=\"font-size:9.5px;border-color:var(--warn);color:var(--warn)\">SHA-256: миллиарды попыток в секунду</div><span class=\"fp-arrow\" style=\"color:var(--good)\">&rarr;</span><div class=\"fp-box good\" style=\"font-size:9.5px\">bcrypt / argon2:<br>намеренно медленно</div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">соль не секрет &mdash; она лежит рядом с хешем в той же строке. её работа не спрятать, а <span style=\"color:var(--txt)\">сделать каждый пароль уникальной задачей</span>, чтобы одну таблицу нельзя было применить ко всей базе</div></div>"
 },
 {
  "id": "pr-cors-preflight",
  "t": "Web",
  "title": "CORS: предполётный запрос",
  "what": "Браузер сам шлёт OPTIONS и без разрешающих заголовков блокирует настоящий запрос — до сервера тот не доходит.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:10px;align-items:center;flex-wrap:wrap;justify-content:center;flex-wrap:nowrap\"><div class=\"fp-box\" style=\"font-size:9.5px\">браузер<br>site-a.kz</div><span class=\"fp-arrow\" style=\"color:var(--warn)\">&rarr;</span><div class=\"fp-col\" style=\"gap:3px;align-items:center\"><div class=\"fp-box\" style=\"font-size:9px;padding:5px 9px;border-color:var(--warn);color:var(--warn)\">OPTIONS /api</div><span style=\"font:8.5px var(--mono);color:var(--mut)\">предполётный, его шлёт браузер сам</span></div><span class=\"fp-arrow\" style=\"color:var(--warn)\">&rarr;</span><div class=\"fp-box acc\" style=\"font-size:9.5px\">api-b.kz</div></div><div class=\"fp-row\" style=\"gap:12px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:270px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">сервер ответил заголовками</span><div class=\"fp-box good\" style=\"font-size:9px;text-align:left;padding:7px 10px\">Allow-Origin: site-a.kz<br>Allow-Methods: POST<br>Allow-Headers: Authorization</div><span style=\"font:9.5px var(--mono);color:var(--good)\">&rarr; браузер шлёт настоящий POST</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:270px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">заголовков нет</span><div class=\"fp-box bad fp-pulse-r\" style=\"font-size:9.5px\">запрос заблокирован<br>в браузере</div><span style=\"font:9.5px var(--mono);color:var(--bad);text-align:center\">на сервер он даже не ушёл &mdash; в его логах пусто</span></div></div><div class=\"fp-row\" style=\"gap:14px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--warn);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">curl работает, браузер нет</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">CORS — правило БРАУЗЕРА, а не защита сервера</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">curl и Postman его просто не соблюдают</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">с куками строже</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">credentials: include требует конкретный Origin</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">звёздочка * перестаёт действовать</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">предполётный запрос уходит не всегда: простой GET или form-POST летит сразу. его вызывают <span style=\"color:var(--txt)\">свои заголовки</span> вроде Authorization или Content-Type: application/json</div></div>"
 },
 {
  "id": "pr-join-types",
  "t": "DB",
  "title": "Как выбирается соединение",
  "what": "Nested Loop, Hash или Merge — планировщик считает стоимость по статистике; ошибётся в оценке строк, и хороший план станет катастрофой.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:12px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:7px;align-items:center;padding:12px 13px;border:1px solid var(--good);border-radius:12px;max-width:200px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">Nested Loop</span><div class=\"fp-row\" style=\"gap:5px;flex-wrap:nowrap\"><div class=\"fp-box good\" style=\"font-size:9px;padding:5px 8px\">10 строк</div><span class=\"fp-arrow\" style=\"color:var(--good)\">&rarr;</span><div class=\"fp-box\" style=\"font-size:9px;padding:5px 8px\">индекс</div></div><span style=\"font:9px var(--mono);color:var(--mut);text-align:center\">на каждую строку слева — точечный поиск справа</span><span style=\"font:9.5px var(--mono);color:var(--good)\">мало строк + индекс</span></div><div class=\"fp-col\" style=\"gap:7px;align-items:center;padding:12px 13px;border:1px solid var(--acc);border-radius:12px;max-width:200px\"><span class=\"fp-tag\" style=\"color:var(--acc);border-color:var(--acc)\">Hash Join</span><div class=\"fp-row\" style=\"gap:5px;flex-wrap:nowrap\"><div class=\"fp-box acc\" style=\"font-size:9px;padding:5px 8px\">хеш<br>в памяти</div><span class=\"fp-arrow\" style=\"color:var(--acc)\">&larr;</span><div class=\"fp-box\" style=\"font-size:9px;padding:5px 8px\">поток<br>строк</div></div><span style=\"font:9px var(--mono);color:var(--mut);text-align:center\">меньшую таблицу целиком в хеш, большую — прогоняем сквозь</span><span style=\"font:9.5px var(--mono);color:var(--acc)\">много строк, индекса нет</span></div><div class=\"fp-col\" style=\"gap:7px;align-items:center;padding:12px 13px;border:1px solid var(--warn);border-radius:12px;max-width:200px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">Merge Join</span><div class=\"fp-row\" style=\"gap:5px;flex-wrap:nowrap\"><div class=\"fp-box\" style=\"font-size:9px;padding:5px 8px;border-color:var(--warn);color:var(--warn)\">1 2 5 9</div><span style=\"font:11px var(--mono);color:var(--warn)\">&#8646;</span><div class=\"fp-box\" style=\"font-size:9px;padding:5px 8px;border-color:var(--warn);color:var(--warn)\">2 5 7 9</div></div><span style=\"font:9px var(--mono);color:var(--mut);text-align:center\">оба входа уже отсортированы — идём навстречу одним проходом</span><span style=\"font:9.5px var(--mono);color:var(--warn)\">сортировка уже есть</span></div></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:wrap;justify-content:center\"><span class=\"fp-token\" style=\"font-size:10px\">выбор делает не ты</span><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><span style=\"font:10px var(--mono);color:var(--txt)\">планировщик считает стоимость по СТАТИСТИКЕ</span></div><div class=\"fp-row\" style=\"gap:14px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">когда он ошибается</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">устарела статистика — оценил 10 строк, пришло 100 000</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">и Nested Loop превращается в 100 000 поисков</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">что делать</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">ANALYZE после массовой загрузки</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">смотреть rows= против actual rows= в плане</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">в плане это первое, на что смотрят: <span style=\"color:var(--txt)\">rows против actual rows</span>. разошлись на порядок — дальше можно не читать, причина в статистике</div></div>"
 },
 {
  "id": "pr-explain-read",
  "t": "DB",
  "title": "Как читать план запроса",
  "what": "Снизу вверх, и первым делом ищут узел, где оценка строк разошлась с фактом — оттуда растёт весь плохой план.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-col\" style=\"gap:0;align-items:stretch;width:100%;max-width:600px\"><div class=\"fp-row\" style=\"gap:8px;align-items:center;justify-content:flex-start;flex-wrap:nowrap;padding:6px 10px;border-left:2px solid var(--good);margin-left:0px\"><span style=\"font:10px var(--mono);color:var(--good);min-width:150px;text-align:left\">Hash Join</span><span style=\"font:9px var(--mono);color:var(--mut);min-width:96px\">cost=0.00..842</span><span style=\"font:9px var(--mono);color:var(--mut);min-width:64px\">rows=1200</span><span style=\"font:9.5px var(--mono);color:var(--good)\">actual rows=1198</span></div><div class=\"fp-row\" style=\"gap:8px;align-items:center;justify-content:flex-start;flex-wrap:nowrap;padding:6px 10px;border-left:2px solid var(--mut);margin-left:18px\"><span style=\"font:10px var(--mono);color:var(--mut);min-width:150px;text-align:left\">&nbsp;&rarr; Seq Scan on orders</span><span style=\"font:9px var(--mono);color:var(--mut);min-width:96px\">cost=0.00..410</span><span style=\"font:9px var(--mono);color:var(--mut);min-width:64px\">rows=10000</span><span style=\"font:9.5px var(--mono);color:var(--mut)\">actual rows=10000</span></div><div class=\"fp-row\" style=\"gap:8px;align-items:center;justify-content:flex-start;flex-wrap:nowrap;padding:6px 10px;border-left:2px solid var(--bad);margin-left:18px\"><span style=\"font:10px var(--mono);color:var(--bad);min-width:150px;text-align:left\">&nbsp;&rarr; Hash</span><span style=\"font:9px var(--mono);color:var(--mut);min-width:96px\">cost=0.00..180</span><span style=\"font:9px var(--mono);color:var(--mut);min-width:64px\">rows=12</span><span style=\"font:9.5px var(--mono);color:var(--bad)\">actual rows=48000</span></div></div><div class=\"fp-row\" style=\"gap:10px;align-items:center;flex-wrap:wrap;justify-content:center\"><div class=\"fp-box bad fp-pulse-r\" style=\"font-size:10px\">оценил 12, пришло 48 000</div><span class=\"fp-arrow\" style=\"color:var(--bad)\">&rarr;</span><span style=\"font:10px var(--mono);color:var(--bad)\">хеш не влез в память и уехал на диск</span></div><div class=\"fp-row\" style=\"gap:14px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--warn);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">cost — не время</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">условные единицы планировщика</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">сравнивать можно только планы между собой</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">EXPLAIN ANALYZE выполняет запрос</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">на UPDATE и DELETE — по-настоящему</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">оборачивай в BEGIN … ROLLBACK</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">BUFFERS показывает правду</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">shared hit — из памяти, read — с диска</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">видно, кто на самом деле тяжёлый</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">читают <span style=\"color:var(--txt)\">снизу вверх</span>: листья выполняются первыми. и первым делом ищут узел, где оценка разошлась с фактом — оттуда растёт весь плохой план</div></div>"
 },
 {
  "id": "pr-wal-durability",
  "t": "DB",
  "title": "WAL: что переживёт падение",
  "what": "Сначала журнал и fsync, только потом сами страницы; подтверждённый коммит восстановится проигрыванием журнала.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:8px;align-items:center;flex-wrap:nowrap;justify-content:center\"><div class=\"fp-box\" style=\"font-size:9.5px;padding:7px 10px;border-color:var(--acc);color:var(--acc)\">COMMIT</div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-box\" style=\"font-size:9.5px;padding:7px 10px;border-color:var(--good);color:var(--good)\">запись в WAL</div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-box\" style=\"font-size:9.5px;padding:7px 10px;border-color:var(--good);color:var(--good)\">fsync на диск</div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-box\" style=\"font-size:9.5px;padding:7px 10px;border-color:var(--acc);color:var(--acc)\">клиенту OK</div></div><div class=\"fp-row\" style=\"gap:10px;align-items:center;flex-wrap:nowrap;justify-content:center\"><span class=\"fp-tag mut\" style=\"color:var(--mut)\">а сами страницы таблицы</span><div class=\"fp-box mut\" style=\"font-size:9.5px\">ещё грязные, в памяти</div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-box\" style=\"font-size:9.5px;border-color:var(--warn);color:var(--warn)\">checkpoint запишет потом</div></div><div class=\"fp-row\" style=\"gap:14px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">упало после fsync WAL</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">при старте проигрывает журнал</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">данные на месте — коммит был подтверждён</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">упало до fsync</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">клиенту OK ещё не ушёл</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">транзакции как не было — это честно</span></div></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:wrap;justify-content:center;padding:11px 14px;border:1px solid var(--bad);border-radius:12px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">synchronous_commit = off</span><span style=\"font:10px var(--mono);color:var(--mut)\">коммит не ждёт fsync: быстрее, но при падении теряются последние транзакции</span></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">это и есть durability: <span style=\"color:var(--txt)\">сначала журнал, потом данные</span>. журнал пишется последовательно, поэтому один fsync дешевле, чем разбросанная запись страниц</div></div>"
 },
 {
  "id": "pr-isolation-levels",
  "t": "DB",
  "title": "Уровни изоляции и аномалии",
  "what": "Что каждый уровень запрещает, чего не показывает таблица (write skew) и чем платят за SERIALIZABLE.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-col\" style=\"gap:0;align-items:stretch;width:100%;max-width:620px\"><div class=\"fp-row\" style=\"gap:6px;align-items:center;flex-wrap:nowrap;padding:5px 0\"><span style=\"font:9px var(--mono);color:var(--mut);min-width:150px\"></span><span style=\"font:9px var(--mono);color:var(--mut);flex:1;text-align:center\">грязное чтение</span><span style=\"font:9px var(--mono);color:var(--mut);flex:1;text-align:center\">неповторяемое</span><span style=\"font:9px var(--mono);color:var(--mut);flex:1;text-align:center\">фантомы</span></div><div class=\"fp-row\" style=\"gap:6px;align-items:center;flex-wrap:nowrap;padding:6px 0;border-top:1px solid var(--line)\"><span style=\"font:10px var(--mono);color:var(--warn);min-width:150px;text-align:left\">READ COMMITTED</span><span style=\"flex:1;text-align:center;font:10px var(--mono);color:var(--good)\">нет</span><span style=\"flex:1;text-align:center;font:10px var(--mono);color:var(--bad)\">ДА</span><span style=\"flex:1;text-align:center;font:10px var(--mono);color:var(--bad)\">ДА</span></div><div class=\"fp-row\" style=\"gap:6px;align-items:center;flex-wrap:nowrap;padding:6px 0;border-top:1px solid var(--line)\"><span style=\"font:10px var(--mono);color:var(--acc);min-width:150px;text-align:left\">REPEATABLE READ</span><span style=\"flex:1;text-align:center;font:10px var(--mono);color:var(--good)\">нет</span><span style=\"flex:1;text-align:center;font:10px var(--mono);color:var(--good)\">нет</span><span style=\"flex:1;text-align:center;font:10px var(--mono);color:var(--bad)\">ДА*</span></div><div class=\"fp-row\" style=\"gap:6px;align-items:center;flex-wrap:nowrap;padding:6px 0;border-top:1px solid var(--line)\"><span style=\"font:10px var(--mono);color:var(--good);min-width:150px;text-align:left\">SERIALIZABLE</span><span style=\"flex:1;text-align:center;font:10px var(--mono);color:var(--good)\">нет</span><span style=\"flex:1;text-align:center;font:10px var(--mono);color:var(--good)\">нет</span><span style=\"flex:1;text-align:center;font:10px var(--mono);color:var(--good)\">нет</span></div></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:wrap;justify-content:center\"><span class=\"fp-tag\" style=\"color:var(--acc);border-color:var(--acc)\">* в PostgreSQL фантомов нет и на REPEATABLE READ</span><span style=\"font:10px var(--mono);color:var(--mut)\">— он даёт снимок, а не блокировки</span></div><div class=\"fp-row\" style=\"gap:14px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">чего таблица НЕ показывает</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">write skew: оба читают, оба пишут разное — и вместе ломают инвариант</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">ловится только SERIALIZABLE</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--warn);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">цена SERIALIZABLE</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">не блокировки, а откаты: ошибка сериализации</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">приложение обязано ретраить</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">уровень по умолчанию в Postgres — <span style=\"color:var(--txt)\">READ COMMITTED</span>: каждый оператор видит свой свежий снимок. поэтому два SELECT в одной транзакции могут вернуть разное, и это не баг</div></div>"
 },
 {
  "id": "pr-cursor-streaming",
  "t": "DB",
  "title": "Выгрузка большой выборки",
  "what": "По умолчанию драйвер тянет весь результат в память; курсор с fetch-size отдаёт порциями, но держит транзакцию.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:16px;align-items:flex-start;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:7px;align-items:center;padding:13px 15px;border:1px solid var(--bad);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">по умолчанию</span><div class=\"fp-row\" style=\"gap:6px;flex-wrap:nowrap\"><div class=\"fp-box\" style=\"font-size:9.5px\">SELECT 5 млн строк</div><span class=\"fp-arrow\" style=\"color:var(--bad)\">&rarr;</span><div class=\"fp-box bad fp-pulse-r\" style=\"font-size:9.5px\">весь результат<br>в память JVM</div></div><div class=\"fp-row\" style=\"gap:6px;align-items:center\"><span class=\"fp-val\" style=\"font-size:20px\">OOM</span><span style=\"font:9.5px var(--mono);color:var(--mut)\">на первой же<br>выгрузке отчёта</span></div></div><div class=\"fp-col\" style=\"gap:7px;align-items:center;padding:13px 15px;border:1px solid var(--good);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">курсор на сервере</span><div class=\"fp-row\" style=\"gap:5px;flex-wrap:nowrap\"><div class=\"fp-box good\" style=\"font-size:9px;padding:5px 8px\">500</div><div class=\"fp-box good\" style=\"font-size:9px;padding:5px 8px\">500</div><div class=\"fp-box good\" style=\"font-size:9px;padding:5px 8px\">500</div><span style=\"font:10px var(--mono);color:var(--good)\">&hellip;</span></div><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">едет порциями, память постоянная</span><div class=\"fp-box mut\" style=\"font-size:9px\">setFetchSize(500)</div></div></div><div class=\"fp-row\" style=\"gap:14px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--warn);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">в Postgres одного fetchSize мало</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">нужен autoCommit = false</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">иначе драйвер всё равно заберёт всё разом</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">курсор держит транзакцию</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">долгая выгрузка = долгая транзакция</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">она тормозит VACUUM и копит bloat</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">то же и в JPA: <span style=\"color:var(--txt)\">getResultList() материализует всё</span>. для выгрузок берут Stream с fetch-size и обязательно закрывают его, иначе курсор течёт</div></div>"
 },
 {
  "id": "pr-replica-lag",
  "t": "DB",
  "title": "Лаг реплики и свои записи",
  "what": "Данные доезжают до реплики с задержкой: пользователь не видит только что созданное, и создаёт второе.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:8px;align-items:center;flex-wrap:nowrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:5px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--acc);border-color:var(--acc)\">мастер</span><div class=\"fp-box acc\" style=\"font-size:9.5px\">INSERT<br>заказ #7</div></div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-col\" style=\"gap:5px;align-items:center\"><span class=\"fp-tag mut\" style=\"color:var(--mut)\">WAL едет</span><div class=\"fp-box mut\" style=\"font-size:9px\">задержка<br>~50–500 мс</div></div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-col\" style=\"gap:5px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">реплика</span><div class=\"fp-box\" style=\"font-size:9.5px;border-color:var(--warn);color:var(--warn)\">заказа #7<br>ещё нет</div></div></div><div class=\"fp-row\" style=\"gap:10px;align-items:center;flex-wrap:wrap;justify-content:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">что видит пользователь</span><span style=\"font:10px var(--mono);color:var(--mut)\">создал заказ &rarr; редирект на список &rarr; <span style=\"color:var(--bad)\">заказа нет</span> &rarr; создаёт второй</span></div><div class=\"fp-row\" style=\"gap:12px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:238px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">read-your-writes</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">после записи читать с мастера — свои же данные</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">обычно на несколько секунд</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:238px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">по позиции WAL</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">запомнить LSN коммита и ждать, пока реплика догонит</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:238px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">не лечится ретраем</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">данные придут, но позже</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">повтор запроса просто попадёт на ту же реплику</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">лаг смотрят не в секундах отставания, а в байтах: <span style=\"color:var(--txt)\">pg_wal_lsn_diff</span>. реплика может «отставать на 0 секунд» просто потому, что на мастере тихо</div></div>"
 },
 {
  "id": "pr-false-sharing",
  "t": "Concurrency",
  "title": "Ложное разделение",
  "what": "Две независимые переменные в одной строке кэша заставляют ядра гонять её друг другу: гонки нет, замков нет, а скорость падает.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:18px;align-items:flex-start;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:8px;align-items:center;padding:13px 15px;border:1px solid var(--bad);border-radius:12px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">два счётчика рядом</span><div class=\"fp-row\" style=\"gap:0;flex-wrap:nowrap;border:1px solid var(--bad);border-radius:9px;overflow:hidden\"><div style=\"width:26px;height:26px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--bad);background:rgba(255,122,133,.18)\">a</div><div style=\"width:26px;height:26px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--bad);background:rgba(255,122,133,.18)\">b</div><div style=\"width:26px;height:26px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--mut);background:transparent\">·</div><div style=\"width:26px;height:26px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--mut);background:transparent\">·</div><div style=\"width:26px;height:26px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--mut);background:transparent\">·</div><div style=\"width:26px;height:26px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--mut);background:transparent\">·</div><div style=\"width:26px;height:26px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--mut);background:transparent\">·</div><div style=\"width:26px;height:26px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--mut);background:transparent\">·</div></div><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">одна строка кэша — 64 байта</span><div class=\"fp-row\" style=\"gap:6px;flex-wrap:nowrap\"><div class=\"fp-box bad\" style=\"font-size:9px;padding:5px 8px\">ядро 1<br>пишет a</div><span class=\"fp-arrow fp-blink\" style=\"color:var(--bad)\">&hArr;</span><div class=\"fp-box bad\" style=\"font-size:9px;padding:5px 8px\">ядро 2<br>пишет b</div></div><span style=\"font:9.5px var(--mono);color:var(--bad);text-align:center\">строка гоняется между кэшами ядер,<br>хотя переменные разные</span></div><div class=\"fp-col\" style=\"gap:8px;align-items:center;padding:13px 15px;border:1px solid var(--good);border-radius:12px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">разведены по строкам</span><div class=\"fp-row\" style=\"gap:5px;flex-wrap:nowrap\"><div class=\"fp-row\" style=\"gap:0;flex-wrap:nowrap;border:1px solid var(--good);border-radius:8px;overflow:hidden\"><div style=\"width:22px;height:24px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--good)\">a</div><div style=\"width:22px;height:24px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--mut)\">·</div><div style=\"width:22px;height:24px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--mut)\">·</div><div style=\"width:22px;height:24px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--mut)\">·</div></div><div class=\"fp-row\" style=\"gap:0;flex-wrap:nowrap;border:1px solid var(--good);border-radius:8px;overflow:hidden\"><div style=\"width:22px;height:24px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--good)\">b</div><div style=\"width:22px;height:24px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--mut)\">·</div><div style=\"width:22px;height:24px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--mut)\">·</div><div style=\"width:22px;height:24px;display:flex;align-items:center;justify-content:center;font:9px var(--mono);border-right:1px solid var(--line);color:var(--mut)\">·</div></div></div><span style=\"font:9.5px var(--mono);color:var(--good);text-align:center\">каждое ядро владеет своей строкой —<br>обмена нет</span><div class=\"fp-box mut\" style=\"font-size:9px\">@Contended или LongAdder</div></div></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:wrap;justify-content:center\"><span class=\"fp-token\" style=\"font-size:10px;color:var(--warn);border-color:var(--warn)\">гонки нет, замков нет</span><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><span style=\"font:10px var(--mono);color:var(--mut)\">а код всё равно медленный — и профайлер показывает «просто цикл»</span></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">это не про корректность, а только про скорость: результат верный, но <span style=\"color:var(--txt)\">кэш-линия ходит по шине</span> между ядрами. @Contended работает лишь с -XX:-RestrictContended, поэтому в жизни берут LongAdder</div></div>"
 },
 {
  "id": "pr-executor-lifecycle",
  "t": "Concurrency",
  "title": "Жизненный цикл ExecutorService",
  "what": "shutdown() не ждёт, shutdownNow() не убивает, потоки не демоны, а submit() прячет исключение внутрь Future.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:8px;align-items:center;flex-wrap:nowrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:4px;align-items:center;max-width:130px\"><div class=\"fp-box\" style=\"font-size:9.5px;padding:7px 10px;border-color:var(--good);color:var(--good)\">работает</div><span style=\"font:8.5px var(--mono);color:var(--mut);text-align:center\">принимает задачи</span></div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-col\" style=\"gap:4px;align-items:center;max-width:130px\"><div class=\"fp-box\" style=\"font-size:9.5px;padding:7px 10px;border-color:var(--warn);color:var(--warn)\">shutdown()</div><span style=\"font:8.5px var(--mono);color:var(--mut);text-align:center\">новые не берёт,<br>старые доделает</span></div><span class=\"fp-arrow\" style=\"color:var(--mut)\">&rarr;</span><div class=\"fp-col\" style=\"gap:4px;align-items:center;max-width:130px\"><div class=\"fp-box\" style=\"font-size:9.5px;padding:7px 10px;border-color:var(--acc);color:var(--acc)\">terminated</div><span style=\"font:8.5px var(--mono);color:var(--mut);text-align:center\">всё завершено</span></div></div><div class=\"fp-row\" style=\"gap:12px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">shutdown() не ждёт</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">возвращает управление сразу</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">нужен awaitTermination(…)</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">shutdownNow() не убивает</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">лишь ставит interrupt</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">задача без проверки флага доработает до конца</span></div></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:wrap;justify-content:center;padding:11px 14px;border:1px solid var(--warn);border-radius:12px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">и главное</span><span style=\"font:10px var(--mono);color:var(--mut)\">потоки по умолчанию <span style=\"color:var(--warn)\">не демоны</span> — забыл shutdown, и JVM не завершится</span></div><div class=\"fp-row\" style=\"gap:10px;align-items:center;flex-wrap:wrap;justify-content:center\"><span class=\"fp-token\" style=\"font-size:9.5px\">submit() глотает исключение</span><span class=\"fp-arrow\" style=\"color:var(--bad)\">&rarr;</span><span style=\"font:10px var(--mono);color:var(--bad)\">оно лежит внутри Future, пока не позовёшь get()</span></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">поэтому упавшая фоновая задача выглядит как «просто ничего не произошло»: ни строчки в логах. у execute() исключение хотя бы дойдёт до <span style=\"color:var(--txt)\">UncaughtExceptionHandler</span></div></div>"
 },
 {
  "id": "pr-work-stealing",
  "t": "Concurrency",
  "title": "Кража задач в ForkJoinPool",
  "what": "Свои задачи берут с головы, чужие крадут с хвоста — поэтому очередь почти без замков, а блокировка в common pool кладёт всё приложение.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:14px;align-items:flex-start;flex-wrap:nowrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">воркер 1</span><div class=\"fp-stack\" style=\"gap:3px\"><div class=\"fp-slot\" style=\"font-size:9px;padding:4px 12px;min-width:74px;border-color:var(--acc);color:var(--acc)\">задача</div><div class=\"fp-slot\" style=\"font-size:9px;padding:4px 12px;min-width:74px;\">задача</div><div class=\"fp-slot\" style=\"font-size:9px;padding:4px 12px;min-width:74px;\">задача</div><div class=\"fp-slot\" style=\"font-size:9px;padding:4px 12px;min-width:74px;\">задача</div></div><span style=\"font:8.5px var(--mono);color:var(--mut)\">своя очередь</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">воркер 2</span><div class=\"fp-stack\" style=\"gap:3px\"><div class=\"fp-slot\" style=\"font-size:9px;padding:4px 12px;min-width:74px;border-color:var(--acc);color:var(--acc)\">задача</div><div class=\"fp-slot\" style=\"font-size:9px;padding:4px 12px;min-width:74px;\">задача</div><div class=\"fp-slot\" style=\"font-size:9px;padding:4px 12px;min-width:74px;\">задача</div></div><span style=\"font:8.5px var(--mono);color:var(--mut)\">своя очередь</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">воркер 3</span><div class=\"fp-stack\" style=\"gap:3px\"><div class=\"fp-slot mut\" style=\"font-size:9px;padding:4px 12px;min-width:74px;border-style:dashed\">пусто</div></div><span style=\"font:8.5px var(--mono);color:var(--mut)\">своя очередь</span></div></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:wrap;justify-content:center\"><div class=\"fp-box bad\" style=\"font-size:9.5px\">воркер 3 освободился</div><span class=\"fp-arrow\" style=\"color:var(--acc)\">&rarr;</span><div class=\"fp-box acc fp-pulse-a\" style=\"font-size:9.5px\">крадёт из ХВОСТА чужой очереди</div></div><div class=\"fp-row\" style=\"gap:12px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">свои берёт с головы, чужие — с хвоста</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">с головы — самые свежие, они горячие в кэше</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">с хвоста — самые крупные, их выгоднее забрать</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">поэтому очередь почти без замков</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">владелец и вор работают с разных концов</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">сталкиваются редко</span></div></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:wrap;justify-content:center;padding:11px 14px;border:1px solid var(--bad);border-radius:12px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">чего нельзя</span><span style=\"font:10px var(--mono);color:var(--mut)\">блокирующий вызов в common pool: воркеров всего <span style=\"color:var(--bad)\">ядер минус один</span>, и параллельные стримы встанут все разом</span></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">на этом же построены <span style=\"color:var(--txt)\">parallelStream</span> и CompletableFuture без своего executor. ждёшь в них сеть или БД — блокируешь пул, общий на всё приложение</div></div>"
 },
 {
  "id": "pr-completablefuture",
  "t": "Concurrency",
  "title": "thenApply, thenCompose, thenCombine",
  "what": "Функция возвращает значение — thenApply, возвращает ещё один CompletableFuture — thenCompose. Как map против flatMap.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-col\" style=\"gap:9px;align-items:stretch;width:100%;max-width:590px\"><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:nowrap;padding:8px 11px;border:1px solid var(--good);border-radius:11px\"><span style=\"font:10px var(--mono);color:var(--good);min-width:104px;text-align:left\">thenApply</span><div class=\"fp-box\" style=\"font-size:9px;padding:5px 8px;min-width:104px;border-color:var(--good);color:var(--good)\">A &rarr; B</div><span style=\"font:9px var(--mono);color:var(--mut);flex:1;text-align:left\">обычная функция</span><span style=\"font:9px var(--mono);color:var(--txt)\">вернёт CF&lt;B&gt;</span></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:nowrap;padding:8px 11px;border:1px solid var(--acc);border-radius:11px\"><span style=\"font:10px var(--mono);color:var(--acc);min-width:104px;text-align:left\">thenCompose</span><div class=\"fp-box\" style=\"font-size:9px;padding:5px 8px;min-width:104px;border-color:var(--acc);color:var(--acc)\">A &rarr; CF&lt;B&gt;</div><span style=\"font:9px var(--mono);color:var(--mut);flex:1;text-align:left\">функция сама асинхронная</span><span style=\"font:9px var(--mono);color:var(--txt)\">склеит, не вложит</span></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:nowrap;padding:8px 11px;border:1px solid var(--warn);border-radius:11px\"><span style=\"font:10px var(--mono);color:var(--warn);min-width:104px;text-align:left\">thenCombine</span><div class=\"fp-box\" style=\"font-size:9px;padding:5px 8px;min-width:104px;border-color:var(--warn);color:var(--warn)\">A + B &rarr; C</div><span style=\"font:9px var(--mono);color:var(--mut);flex:1;text-align:left\">две независимые задачи</span><span style=\"font:9px var(--mono);color:var(--txt)\">дождётся обеих</span></div></div><div class=\"fp-row\" style=\"gap:9px;align-items:center;flex-wrap:wrap;justify-content:center\"><div class=\"fp-box bad\" style=\"font-size:9.5px\">thenApply на асинхронной функции</div><span class=\"fp-arrow\" style=\"color:var(--bad)\">&rarr;</span><div class=\"fp-box bad fp-pulse-r\" style=\"font-size:9.5px\">CF&lt;CF&lt;B&gt;&gt;</div><span style=\"font:10px var(--mono);color:var(--mut)\">— распаковывать вручную</span></div><div class=\"fp-row\" style=\"gap:12px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--bad);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">исключение не бросается</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">оно едет внутри цепочки и всплывёт в join()</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">без exceptionally или handle — тишина</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--warn);border-radius:12px;max-width:262px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">без своего executor</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">всё уедет в common ForkJoinPool</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">для I/O это неверно — давай отдельный пул</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">правило простое: функция возвращает <span style=\"color:var(--txt)\">значение</span> — thenApply, возвращает <span style=\"color:var(--txt)\">ещё один CompletableFuture</span> — thenCompose. Как map против flatMap</div></div>"
 },
 {
  "id": "pr-longadder",
  "t": "Concurrency",
  "title": "LongAdder против AtomicLong",
  "what": "Одна ячейка с CAS в цикле упирается в конкуренцию; LongAdder разносит запись по ячейкам и складывает их при чтении.",
  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"gap:18px;align-items:flex-start;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:8px;align-items:center;padding:13px 15px;border:1px solid var(--bad);border-radius:12px\"><span class=\"fp-tag\" style=\"color:var(--bad);border-color:var(--bad)\">AtomicLong под нагрузкой</span><div class=\"fp-row\" style=\"gap:6px;flex-wrap:nowrap\"><div class=\"fp-box\" style=\"font-size:9px;padding:5px 7px\">1</div><div class=\"fp-box\" style=\"font-size:9px;padding:5px 7px\">2</div><div class=\"fp-box\" style=\"font-size:9px;padding:5px 7px\">3</div><div class=\"fp-box\" style=\"font-size:9px;padding:5px 7px\">4</div></div><span class=\"fp-arrow\" style=\"color:var(--bad)\">&darr;</span><div class=\"fp-box bad fp-pulse-r\" style=\"font-size:10px\">одна ячейка<br>CAS в цикле</div><span style=\"font:9.5px var(--mono);color:var(--bad);text-align:center\">чем больше потоков,<br>тем чаще промах и повтор</span></div><div class=\"fp-col\" style=\"gap:8px;align-items:center;padding:13px 15px;border:1px solid var(--good);border-radius:12px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">LongAdder</span><div class=\"fp-row\" style=\"gap:6px;flex-wrap:nowrap\"><div class=\"fp-box\" style=\"font-size:9px;padding:5px 7px\">1</div><div class=\"fp-box\" style=\"font-size:9px;padding:5px 7px\">2</div><div class=\"fp-box\" style=\"font-size:9px;padding:5px 7px\">3</div><div class=\"fp-box\" style=\"font-size:9px;padding:5px 7px\">4</div></div><div class=\"fp-row\" style=\"gap:5px;flex-wrap:nowrap\"><div class=\"fp-box good\" style=\"font-size:9px;padding:5px 7px\">+7</div><div class=\"fp-box good\" style=\"font-size:9px;padding:5px 7px\">+3</div><div class=\"fp-box good\" style=\"font-size:9px;padding:5px 7px\">+9</div><div class=\"fp-box good\" style=\"font-size:9px;padding:5px 7px\">+2</div></div><span class=\"fp-arrow\" style=\"color:var(--good)\">&darr;</span><div class=\"fp-box good\" style=\"font-size:10px\">sum() складывает<br>ячейки при чтении</div></div></div><div class=\"fp-row\" style=\"gap:12px;align-items:stretch;flex-wrap:wrap;justify-content:center\"><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--good);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--good);border-color:var(--good)\">когда LongAdder</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">пишут часто, читают редко</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">счётчики запросов, метрики, статистика</span></div><div class=\"fp-col\" style=\"gap:6px;align-items:center;padding:12px 14px;border:1px solid var(--warn);border-radius:12px;max-width:250px\"><span class=\"fp-tag\" style=\"color:var(--warn);border-color:var(--warn)\">когда AtomicLong</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">нужно точное текущее значение здесь и сейчас</span><span style=\"font:9.5px var(--mono);color:var(--mut);text-align:center\">нужен compareAndSet или getAndIncrement как идентификатор</span></div></div><div style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:560px\">sum() не атомарен: он <span style=\"color:var(--txt)\">складывает ячейки на ходу</span>, пока другие пишут. для счётчика это нормально, для выдачи уникальных номеров — нет</div></div>"
 }
]);
